 ['Dem Coffee','Sosyal medya / Marka','Her paylaşımda tanınan bir görsel dil.','morrow','coffee','Yeni bir kafe markasının ürün, mekân ve günlük iletişimini aynı yayın planında birleştirmek hedeflendi.','Fotoğraf kullanımı, renkler ve kısa metinler için tutarlı bir içerik düzeni kuruldu.','Konsept olarak paylaşım serisi, kampanya kapağı ve içerik takvimi hazırlandı.']
 ];
 foreach($projects as $i=>$r){$existing=$i<3?record('projects',$i+1):null;if($existing&&!$existing['is_demo'])continue;
