 foreach(records('services') as $service){$m=meta('services',(int)$service['id']);if(empty($m['image_id'])){$m['image_id']=match($service['slug']){'mobil-uygulama'=>$media['mobile'],'marka-tasarim','e-ticaret','sosyal-medya-yonetimi'=>$media['coffee'],'yazilim-entegrasyonu','ozel-yazilim','crm-otomasyon','web-yazilim'=>$media['flow'],default=>$media['architecture']};meta_save('services',(int)$service['id'],$m);}if(!query('SELECT id FROM faqs WHERE service_id=? LIMIT 1',[$service['id']])->fetchColumn())query('INSERT INTO faqs (question,answer,service_id,sort_order) VALUES (?,?,?,?)',[$service['name'].' projesi için neleri hazırlamalıyım?','Mevcut çalışmalarınız, hedefleriniz, içerik kaynaklarınız ve ihtiyaç duyduğunuz bağlantıları paylaşmanız yeterli. İlk görüşmede eksikleri ve proje kapsamını birlikte çıkarırız.',$service['id'],1]);}
 foreach([['Demo · Morrow Coffee','morrow@example.test','E-Ticaret','Ürünlerimiz için filtrelenebilir bir mağaza ve kolay yönetilebilir sipariş ekranı planlıyoruz. Bu kayıt paneli göstermek için örnektir.'],['Demo · Forma Studio','forma@example.test','Web Tasarım','Mimari işlerimizi büyük fotoğraflarla sergileyen bir portföy sitesi düşünüyoruz. Bu kayıt örnek proje talebidir.'],['Demo · Akış','akis@example.test','Yazılım Entegrasyonu','Sipariş ve stok bilgisini bir araya getirmek istiyoruz. Bu kayıt müşteri takip ekranını göstermek için hazırlanmıştır.']] as $r){query('INSERT INTO leads (name,email,phone,service,message,status,created_at) VALUES (?,?,?,?,?,?,?)',[$r[0],$r[1],'',$r[2],$r[3],'new',gmdate('c')]);$lid=(int)db()->lastInsertId();query('INSERT INTO lead_notes (lead_id,note,actor,created_at) VALUES (?,?,?,?)',[$lid,'Demo takip notu: ihtiyaç görüşmesi, kapsam ve içerik kaynakları değerlendirilir.','Demo içerik',gmdate('c')]);}
 $localNotes=['İstanbul'=>'Birden fazla ilçeden gelen mobil kullanıcıların keşif ve başvuru adımlarını telefonda rahat tamamlayabilmesi hedeflenir. Kapsam görüşmesinde konum izni gerekip gerekmediği ve kullanıcıya sunulan alternatifler değerlendirilir.','Ankara'=>'Kurumsal birimler arasında veri aktarımı yapılacaksa kayıt sahipliği, alan eşleştirmeleri ve onay adımları proje başlangıcında belirlenir. Bu örnek sayfa fiziksel ofis veya yapılmış müşteri işi iddiası taşımaz.','İzmir'=>'Özel yazılım kapsamı işletmenin gerçek iş akışına göre çıkarılır. Tekrarlayan veri girişi, görev atama ve raporlama ihtiyacı örnek senaryolarla değerlendirilir; çevrim içi görüşmelerle kapsam netleştirilir.','Bursa'=>'Sosyal medya içeriğinde ürün veya hizmet bilgisinin kim tarafından doğrulanacağı ve yayın öncesi onay akışı belirlenir. Fotoğraf kaynakları, paylaşım takvimi ve ölçüm beklentisi birlikte planlanır.','Antalya'=>'Kurumsal sitenin dil ihtiyacı, hizmet dönemleri ve mobil başvuru akışı başlangıçta değerlendirilir. Gerçek hizmet kapasitesine uygun içerik hazırlanır; iletişim ve teklif adımları açıkça belirtilir.','Kocaeli'=>'Talep takibinde hangi ekibin hangi kaydı görebileceği ve müşteriye dönüş sorumluluğu tanımlanır. Bu kapsam örneğinde fiziksel ofis veya sonuç garantisi verilmez; süreç görüşmeyle işletmeye uyarlanır.'];
 foreach(array_keys($localNotes) as $i=>$cityName){$city=query('SELECT * FROM cities WHERE name=?',[$cityName])->fetch();$service=record('services',$i+7);if(!$city||!$service||query('SELECT id FROM pages WHERE service_id=? AND city_id=?',[$service['id'],$city['id']])->fetchColumn())continue;$p=generate_page($service,$city);$p['status']='published';$p['reviewed']=1;$cols=implode(',',array_keys($p));$marks=implode(',',array_fill(0,count($p),'?'));query("INSERT INTO pages ($cols) VALUES ($marks)",array_values($p));meta_save('pages',(int)db()->lastInsertId(),['unique_value'=>$localNotes[$cityName],'noindex'=>1,'demo'=>1,'image_id'=>$media['flow']]);}
